// 1. TEXT MODE: Writing data
FILE *fp_w = fopen("log.txt", "w");
if (fp_w == NULL) return -1;

char name[] = "User A";
int score = 42;

fprintf(fp_w, "Name: %s\nScore: %d\n", name, score);
fflush(fp_w); // Ensure immediate write
fclose(fp_w);

// 2. TEXT MODE: Reading data
FILE *fp_r = fopen("log.txt", "r");
if (fp_r == NULL) return -1;

char buffer[80];
// Reads until newline or EOF
while (fgets(buffer, sizeof(buffer), fp_r) != NULL) {
    // Process buffer contents
}
fclose(fp_r);

// 3. BINARY MODE: Writing/Reading structs
typedef struct { int id; float value; } Config;
Config cfg = {101, 3.14};

FILE *fp_bin = fopen("data.bin", "wb+");
if (fp_bin == NULL) return -1;

// Writing: write 1 item of size(Config)
fwrite(&cfg, sizeof(Config), 1, fp_bin);
fseek(fp_bin, 0, SEEK_SET);

// Reading: read 1 item into new_cfg
Config new_cfg;
fread(&new_cfg, sizeof(Config), 1, fp_bin);

fclose(fp_bin);
